package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;
import java.util.concurrent.atomic.AtomicLong;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");

    /** Monotonically increasing sequence stamped on every OWNER_CREATED event across all creates. */
    private static final AtomicLong EVENT_SEQ = new AtomicLong();

    public void service(@Val Owner owner, OwnerMapper ownerMapper,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        auditLogger.info("Owner created id={} memberId={} registrationDate={} membershipLevel={}",
                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), dto.getMembershipLevel());
        auditLogger.info(ownerCreatedEvent(EVENT_SEQ.incrementAndGet(), owner, dto.getMembershipLevel()));
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }

    /**
     * Renders the immutable structured OWNER_CREATED event. The {@code memberId} field carries the
     * owner's primary identifier, now that the customerCode and membershipNumber have been unified
     * into the memberId; {@link #primaryIdentifier(Owner)} is the single place that resolves it.
     */
    private static String ownerCreatedEvent(long seq, Owner owner, int membershipLevel) {
        return "{\"seq\":" + seq
                + ",\"ownerId\":" + owner.getId()
                + ",\"memberId\":" + jsonString(primaryIdentifier(owner))
                + ",\"membershipLevel\":" + membershipLevel
                + ",\"event\":\"OWNER_CREATED\"}";
    }

    /** The owner's primary identifier: the unified memberId. */
    private static String primaryIdentifier(Owner owner) {
        return owner.getMemberId();
    }

    /** Renders a string as a JSON literal (quoted, with the mandatory escapes), or {@code null}. */
    private static String jsonString(String value) {
        if (value == null) {
            return "null";
        }
        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"' -> sb.append("\\\"");
                case '\\' -> sb.append("\\\\");
                case '\n' -> sb.append("\\n");
                case '\r' -> sb.append("\\r");
                case '\t' -> sb.append("\\t");
                default -> {
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    }
                    else {
                        sb.append(c);
                    }
                }
            }
        }
        return sb.append('"').toString();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.function.common.FiscalYear;
import org.springframework.samples.petclinic.rest.function.common.Localities;

/**
 * Assigns the owner's unified {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where
 * REGION is the region derived from the owner's postcode (falling back to the city table), FY is the
 * two-digit fiscal year (starting 1 July) of the business-day-adjusted {@code registrationDate},
 * HASH8 is the first eight upper-case hex characters of SHA-256 over the normalized telephone
 * concatenated with the last name, and CHK is a single Luhn check digit computed over the digits of
 * {@code <REGION><FY><HASH8>} (e.g. {@code NSW261A2B3C4D7}). Runs after telephone normalization and
 * the registration date default, so the hash is taken over the stored, normalized (E.164) telephone
 * and the fiscal year is known.
 *
 * <p>If the computed memberId collides with an existing owner's {@code memberId}, {@code -<n>} is
 * appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners always
 * receive distinct member ids. Runs before the owner is saved, so it is matched only against owners
 * already present.
 */
public class AssignMemberId {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String region = Localities.region(owner.getPostcode(), owner.getCity());
        String fy = String.format("%02d", FiscalYear.endingYear(owner.getRegistrationDate()) % 100);
        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
        String core = region + fy + hash8;
        String base = core + luhn(core);

        Set<String> existing = new HashSet<>();
        for (Owner other : ownerRepository.findAll()) {
            existing.add(other.getMemberId());
        }

        String memberId = base;
        for (int n = 2; existing.contains(memberId); n++) {
            memberId = base + "-" + n;
        }
        owner.setMemberId(memberId);
    }

    /**
     * The single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
     * characters (the region letters and hex letters) are ignored; the digits are processed
     * right-to-left, doubling every second digit starting with the rightmost and subtracting 9 from
     * any doubled value above 9; the check digit is {@code (10 - (sum % 10)) % 10}.
     */
    private static int luhn(String value) {
        int sum = 0;
        boolean dbl = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /** First {@code length} upper-case hex characters of SHA-256({@code value}). */
    private static String shaHex(String value, int length) {
        return sha256hex(value).substring(0, length).toUpperCase();
    }

    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
    private static String sha256hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}
